// 跟进节奏: 首次触达后第 3/7/14 天各跟进一次;已回复/已成交/已流失/退订 的线索跳过
const STOP = ['已回复', '已成交', '已流失', '退订'];
const STEPS = [
  { day: 3,  angle: '补充一个与其行业相关的具体案例' },
  { day: 7,  angle: '分享一个可量化的结果或数据' },
  { day: 14, angle: '礼貌收尾,询问是否有更合适的对接人' },
];
const out = [];
for (const item of $input.all()) {
  const p = item.json.properties ?? {};
  const status = p['状态']?.select?.name ?? '';
  const email = p['邮箱']?.email ?? '';
  const grade = p['等级']?.select?.name ?? '';
  const lastContact = p['最后联系']?.date?.start;
  const step = Number(p['跟进步数']?.number ?? 0);
  if (!email || STOP.includes(status) || grade === 'C') continue;
  if (!lastContact || step >= STEPS.length) continue;
  const days = Math.floor((Date.now() - new Date(lastContact).getTime()) / 86400000);
  const target = STEPS[step];
  if (days < target.day) continue;
  const name = (item.json.properties?.['Name']?.title ?? item.json.properties?.['名称']?.title ?? [])[0]?.plain_text ?? '';
  out.push({ json: { pageId: item.json.id, email, name, step: step + 1, angle: target.angle, isLast: step + 1 === STEPS.length } });
}
return out;
